//! Differential tests: our lighting engine vs. frames rendered by the stock 0.0.18 firmware's
//! own code in the emulator (fixtures/rgb/*.txt, generated by fixtures/gen_rgb.py).
//!
//! Each fixture lists harness options (effect, colour, brightness, speed, LED flags, start tick,
//! tick step, held keys, static colours, Caps/Fn overlays, lights off) and per-frame RGB of
//! all 85 LEDs. We set up the same profile (factory profile 0 + those options), render the same
//! ticks with the same key states and compare every byte. The harness starts both PRNGs at the
//! firmware's power-on seeds, as `Lighting::new` does, so the random effects match too.

use std::fs;
use std::path::PathBuf;
use zent_core::config::{b2, Profile};
use zent_core::defaults;
use zent_core::layout::LED_COUNT;
use zent_core::lighting::Lighting;

struct Case {
    name: String,
    opts: Vec<(String, String)>,
    frames: Vec<(u32, Vec<u8>)>,
}

fn load() -> Vec<Case> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/rgb");
    let mut v: Vec<_> = fs::read_dir(&dir).unwrap().map(|e| e.unwrap().path()).collect();
    v.sort();
    v.into_iter()
        .map(|p| {
            let txt = fs::read_to_string(&p).unwrap();
            let mut lines = txt.lines();
            let hdr = lines.next().unwrap().trim_start_matches("# ");
            let opts = hdr
                .split_whitespace()
                .map(|kv| match kv.split_once('=') {
                    Some((k, v)) => (k.to_string(), v.to_string()),
                    None => (kv.to_string(), String::new()),
                })
                .collect();
            let frames = lines
                .map(|l| {
                    let (t, hex) = l.split_once(' ').unwrap();
                    let b = (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect();
                    (t.parse().unwrap(), b)
                })
                .collect();
            Case { name: p.file_stem().unwrap().to_str().unwrap().to_string(), opts, frames }
        })
        .collect()
}

fn num(c: &Case, k: &str) -> u32 {
    c.opts.iter().find(|(a, _)| a == k).map(|(_, v)| v.parse().unwrap()).unwrap()
}

/// Render a case with our engine; returns per-frame output.
fn render(c: &Case) -> Vec<Vec<u8>> {
    let mut p = Profile::zeroed();
    defaults::profile(&mut p, 0);
    p.0[b2::RGB_CONFIG..b2::RGB_CONFIG + 6].copy_from_slice(&[
        (num(c, "effect") as u8) << 2 | 1,
        num(c, "h") as u8,
        num(c, "s") as u8,
        num(c, "bright") as u8,
        num(c, "speed") as u8,
        num(c, "flags") as u8,
    ]);
    let has = |k: &str| c.opts.iter().any(|(a, _)| a == k);
    p.0[b2::RGB_ENABLE] = if has("off") { 0 } else { 1 };
    p.0[b2::CAP_ENABLE] = 1;
    p.0[b2::RGB_FN_ENABLE] = 1;
    p.0[b2::SLEEP_SECOND_CNT..b2::SLEEP_SECOND_CNT + 4].fill(0);
    p.0[b2::RGB..b2::RGB + 3 * LED_COUNT].fill(0xFF);
    p.0[b2::RGB_SOLID_ENABLE..b2::RGB_SOLID_ENABLE + LED_COUNT].fill(0);
    for (k, v) in &c.opts {
        if k == "static" {
            let (led, col) = v.split_once('=').unwrap();
            let led: usize = led.parse().unwrap();
            p.0[b2::RGB_SOLID_ENABLE + led] = 1;
            for j in 0..3 {
                p.0[b2::RGB + 3 * led + j] = u8::from_str_radix(&col[2 * j..2 * j + 2], 16).unwrap();
            }
        }
    }
    let mut l = Lighting::new();
    l.configure(&mut p);
    l.set_host_leds(if has("caps") { 2 } else { 0 });
    l.set_fn_held(has("fn"));
    let presses: Vec<(usize, usize, usize)> = c
        .opts
        .iter()
        .filter(|(k, _)| k == "press")
        .map(|(_, v)| {
            let (k, r) = v.split_once('@').unwrap();
            let (a, b) = r.split_once('-').unwrap();
            (k.parse().unwrap(), a.parse().unwrap(), b.parse().unwrap())
        })
        .collect();
    let height = num(c, "height") as i32;
    let full = 3420;
    let depth = (((full - 100 - height.clamp(100, full - 100)) * 255) / (full - 200)) as u8;
    let mut out = [[0u8; 3]; LED_COUNT];
    c.frames
        .iter()
        .enumerate()
        .map(|(i, (t, _))| {
            for &(k, a, b) in &presses {
                let down = a <= i && i <= b;
                l.press_key(k, down);
                l.set_depth(k, if down { depth } else { 0 });
            }
            l.render_at_tick(*t, &p, &mut out);
            out.iter().flatten().copied().collect()
        })
        .collect()
}

#[test]
fn effects_match_stock_frame_by_frame() {
    let cases = load();
    assert!(cases.len() > 100, "fixtures missing");
    let mut bad = Vec::new();
    for c in &cases {
        let got = render(c);
        for (i, ((t, want), g)) in c.frames.iter().zip(&got).enumerate() {
            let diffs: Vec<usize> = (0..want.len()).filter(|&j| want[j] != g[j]).collect();
            if !diffs.is_empty() {
                let j = diffs[0];
                bad.push(format!(
                    "{} frame {i} t={t}: {} bytes differ, first LED {} got {:?} want {:?}",
                    c.name,
                    diffs.len(),
                    j / 3,
                    &g[j / 3 * 3..j / 3 * 3 + 3],
                    &want[j / 3 * 3..j / 3 * 3 + 3]
                ));
                break;
            }
        }
    }
    assert!(bad.is_empty(), "{} of {} cases differ:\n{}", bad.len(), cases.len(), bad.join("\n"));
}
